// Set the keyword to search here
const keyword = 'mua bàn gỗ';
return [{ json: { keyword } }];

const data = $input.first().json;
const keyword = $('Set Keyword').first().json.keyword;

// --- Search ID from SerpAPI ---
const searchId = (data.search_metadata && data.search_metadata.id) || ('local_' + Date.now());

// --- AI Overview ---
let aiOverview = null;
let aiOverviewRefs = [];
const aio = data.ai_overview;
if (aio) {
  if (typeof aio === 'string') aiOverview = aio;
  else if (aio.text_blocks) aiOverview = aio.text_blocks.map(b => b.snippet || b.text || '').join('\n').trim();
  else if (aio.text) aiOverview = aio.text;
  else if (aio.snippet) aiOverview = aio.snippet;
  const refs = aio.references || aio.sources || [];
  aiOverviewRefs = refs.map(r => ({ title: r.title || '', url: r.link || r.url || '', snippet: r.snippet || '' }));
}
if (!aiOverview && data.answer_box) {
  const ab = data.answer_box;
  aiOverview = ab.answer || ab.snippet || ab.result || null;
}
if (!aiOverview && data.knowledge_graph && data.knowledge_graph.description) {
  aiOverview = data.knowledge_graph.description;
}

const knowledgeGraph = data.knowledge_graph || null;
const answerBox = data.answer_box || null;
const totalResults = data.search_information ? (data.search_information.total_results_text || String(data.search_information.total_results || '')) : null;

// --- Top 5 organic results ---
const organic = data.organic_results || [];
const topResults = organic.slice(0, 5).map((r, i) => {
  let domain = '';
  try { domain = new URL(r.link).hostname; } catch(e) {}
  return { position: r.position || (i + 1), title: r.title || '', url: r.link || '', snippet: r.snippet || '', display_url: r.displayed_link || '', domain };
});

const url1 = topResults[0] ? topResults[0].url : '';
const url2 = topResults[1] ? topResults[1].url : '';

return [{ json: {
  search_id: searchId,
  keyword,
  ai_overview: aiOverview,
  ai_overview_references: aiOverviewRefs,
  knowledge_graph: knowledgeGraph,
  answer_box: answerBox,
  total_results: totalResults,
  organic_results: topResults,
  raw_response: data,
  searched_at: new Date().toISOString(),
  fetch_url_1: url1,
  fetch_url_2: url2
} }];

const searchData = $input.first().json;

return [{ json: {
  search_id: searchData.search_id,
  keyword: searchData.keyword,
  ai_overview_text: searchData.ai_overview,
  ai_overview_references: searchData.ai_overview_references,
  knowledge_graph: searchData.knowledge_graph,
  answer_box: searchData.answer_box,
  searched_at: searchData.searched_at
} }];

const searchData = $('Extract Search Data').first().json;
const searchId = searchData.search_id;
const organicResults = searchData.organic_results || [];

// Output up to 5 items — one per organic result
return organicResults.map(r => ({
  json: {
    search_id: searchId,
    position: r.position,
    title: r.title,
    url: r.url,
    snippet: r.snippet,
    display_url: r.display_url,
    domain: r.domain
  }
}));

const searchData = $('Extract Search Data').first().json;
const html = $input.first().json.body || '';
const url = searchData.fetch_url_1;
const PAGE_NUMBER = 1;

if (!html) return [{ json: { search_id: searchData.search_id, page_number: PAGE_NUMBER, url, title: '', title_length: 0, meta_description: '', meta_description_length: 0, meta_keywords: '', og_title: '', og_description: '', og_image: '', og_url: '', canonical_url: '', favicon: '', viewport: '', charset: '', robots_meta: '', h1_tags: '[]', h1_count: 0, h2_tags: '[]', h2_count: 0, h3_tags: '[]', h3_count: 0, total_links: 0, internal_links: 0, external_links: 0, total_images: 0, images_with_alt: 0, images_without_alt: 0, word_count: 0, content: '', links_json: '[]', images_json: '[]' } }];

function getAttr(tag, attr) {
  const re = new RegExp(attr + '=["\']([^"\']*)["\']', 'i');
  const m = tag.match(re);
  return m ? m[1] : null;
}
function matchAll(str, re) {
  const results = []; let m;
  while ((m = re.exec(str)) !== null) results.push(m);
  return results;
}
function getMeta(name) {
  const re = new RegExp('<meta[^>]*name=["\']' + name + '["\'][^>]*>', 'i');
  const m = html.match(re);
  return m ? (getAttr(m[0], 'content') || '') : '';
}
function getOg(prop) {
  const re = new RegExp('<meta[^>]*property=["\']' + prop + '["\'][^>]*>', 'i');
  const m = html.match(re);
  return m ? (getAttr(m[0], 'content') || '') : '';
}
function getHeadings(tag) {
  const re = new RegExp('<' + tag + '[^>]*>(.*?)<\\/' + tag + '>', 'gis');
  return matchAll(html, re).map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(t => t);
}

// Title
const titleMatch = html.match(/<title[^>]*>(.*?)<\/title>/is);
const title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : '';

// Meta tags
const metaDesc = getMeta('description');
const metaKeywords = getMeta('keywords');
const viewport = getMeta('viewport');
const robots = getMeta('robots');
const ogTitle = getOg('og:title');
const ogDesc = getOg('og:description');
const ogImage = getOg('og:image');
const ogUrl = getOg('og:url');

// Charset
const charsetMatch = html.match(/<meta[^>]*charset=["']?([^"'\\s>]+)/i);
const charset = charsetMatch ? charsetMatch[1] : 'utf-8';

// Canonical
const canonicalMatch = html.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']*)["']/i);
const canonical = canonicalMatch ? canonicalMatch[1] : '';

// Favicon
const faviconMatch = html.match(/<link[^>]*rel=["'][^"']*icon[^"']*["'][^>]*href=["']([^"']*)["']/i);
const favicon = faviconMatch ? faviconMatch[1] : '';

// Headings
const h1 = getHeadings('h1');
const h2 = getHeadings('h2');
const h3 = getHeadings('h3');

// Links - detect domain for internal/external
let domain = '';
try { domain = new URL(url).hostname; } catch(e) {}
const linkMatches = matchAll(html, /<a[^>]*href=["']([^"']*)["']/gi);
const links = linkMatches.map(m => m[1]);
const intLinks = links.filter(l => l.startsWith('/') || l.includes(domain)).length;

// Images
const imgTags = matchAll(html, /<img[^>]*>/gi);
const images = imgTags.map(m => getAttr(m[0], 'src')).filter(Boolean);
const imagesWithAlt = imgTags.filter(m => { const a = getAttr(m[0], 'alt'); return a && a.length > 0; }).length;

// Body text & word count
const bodyMatch = html.match(/<body[^>]*>(.*)<\/body>/is);
let bodyText = '';
if (bodyMatch) {
  bodyText = bodyMatch[1]
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
const wordCount = bodyText.split(/\s+/).filter(w => w.length > 0).length;

return [{ json: {
  search_id: searchData.search_id,
  page_number: PAGE_NUMBER,
  url,
  title,
  title_length: title.length,
  meta_description: metaDesc,
  meta_description_length: metaDesc.length,
  meta_keywords: metaKeywords,
  og_title: ogTitle,
  og_description: ogDesc,
  og_image: ogImage,
  og_url: ogUrl,
  canonical_url: canonical,
  favicon,
  viewport,
  charset,
  robots_meta: robots,
  h1_tags: JSON.stringify(h1),
  h1_count: h1.length,
  h2_tags: JSON.stringify(h2),
  h2_count: h2.length,
  h3_tags: JSON.stringify(h3),
  h3_count: h3.length,
  total_links: links.length,
  internal_links: intLinks,
  external_links: links.length - intLinks,
  total_images: images.length,
  images_with_alt: imagesWithAlt,
  images_without_alt: images.length - imagesWithAlt,
  word_count: wordCount,
  content: bodyText.substring(0, 5000),
  links_json: JSON.stringify(links.slice(0, 500)),
  images_json: JSON.stringify(images.slice(0, 200))
} }];

